import { useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, Boxes, Check, CheckCheck, ChevronDown, ChevronRight, CircleAlert, Clock3, Download, Droplets, FileCheck2, Filter, HeartHandshake, LayoutDashboard, LoaderCircle, LogOut, MapPin, Menu, Package, Plus, RefreshCw, Route as RouteIcon, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Stethoscope, Truck, Users, Warehouse as WarehouseIcon, X } from 'lucide-react';
import { NetworkMap } from './NetworkMap';
import { ITEMS, ITEM_NAMES, UNITS, PRIORITY, num, remaining, total, label, time } from './types';
import type { Activity as ActivityEvent, Item, Quantities, Snapshot } from './types';

type Page = 'overview' | 'needs' | 'resources' | 'planning' | 'deliveries' | 'reports';
type ModalKind = 'location' | 'request' | 'warehouse' | 'restock' | 'vehicle' | 'verify' | 'settings' | 'reset';
type ModalState = { kind: ModalKind; id?: string };
type Save = (path: string, body?: unknown, method?: string, message?: string) => Promise<boolean>;
const NAV = [{ id: 'overview', label: 'Overview', icon: LayoutDashboard }, { id: 'needs', label: 'Community needs', icon: HeartHandshake }, { id: 'resources', label: 'Resources', icon: Boxes }, { id: 'planning', label: 'Allocation & routes', icon: RouteIcon }, { id: 'deliveries', label: 'Deliveries', icon: Truck }, { id: 'reports', label: 'Reports & activity', icon: Activity }] as const;

function apiError(detail: unknown): string {
  if (typeof detail === 'string') return detail;
  if (Array.isArray(detail)) return detail.map(x => `${x.loc?.slice(1).join('.') || 'Input'}: ${x.msg || 'Invalid value'}`).join('; ');
  return 'The request could not be completed. Please try again.';
}
async function request<T>(path: string, csrf = '', body?: unknown, method = 'GET'): Promise<T> {
  const response = await fetch(`/api${path}`, { method, credentials: 'same-origin', headers: { ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}), ...(csrf ? { 'X-CSRF-Token': csrf } : {}) }, ...(body !== undefined ? { body: JSON.stringify(body) } : {}) });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(apiError(result.detail));
  return result as T;
}
function Brand({ inverse = false }: { inverse?: boolean }) { return <div className={`brand ${inverse ? 'brand-inverse' : ''}`}><span className="brand-mark"><HeartHandshake size={25} strokeWidth={1.7} /></span><div>relief<span>link</span><small>RESPONSE, CONNECTED.</small></div></div>; }
function Badge({ value, children }: { value: string; children?: ReactNode }) { return <span className={`badge badge-${value.toLowerCase().replace(/ /g, '-')}`}><i />{children || label(value)}</span>; }
function ItemIcon({ item, size = 16 }: { item: Item; size?: number }) { const Icon = item === 'food' ? Package : item === 'water' ? Droplets : Stethoscope; return <Icon size={size} />; }
function Cargo({ q, compact = false }: { q: Quantities; compact?: boolean }) { return <div className={`cargo ${compact ? 'cargo-compact' : ''}`}>{ITEMS.map(k => <span key={k} title={ITEM_NAMES[k]}><ItemIcon item={k} size={14} /><strong>{num(q[k])}</strong><small>{UNITS[k]}</small></span>)}</div>; }
function Empty({ icon = <Boxes size={26} />, title, children, action }: { icon?: ReactNode; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty"><span className="empty-icon">{icon}</span><h3>{title}</h3><p>{children}</p>{action}</div>; }
function SectionHead({ title, subtitle, right }: { title: string; subtitle?: string; right?: ReactNode }) { return <div className="section-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{right}</div>; }
function ActivityList({ events, limit = 6 }: { events: ActivityEvent[]; limit?: number }) { return <div className="activity-list">{events.slice(0, limit).map((e, i) => <div className="activity-event" key={e.id}><span className={`activity-icon ${i === 0 ? 'activity-icon-new' : ''}`}><Check size={13} /></span><div><p>{e.detail}</p><small>{e.user_name} <span>·</span> {label(e.action)}</small></div><time title={new Date(e.created_at).toLocaleString()}>{time(e.created_at)}</time></div>)}{!events.length && <p className="muted padding">Activity will appear as your team works.</p>}</div>; }

function Login({ onLogin, error }: { onLogin: (email: string, password: string) => Promise<void>; error: string }) {
  const [email, setEmail] = useState('coordinator@relieflink.local');
  const [password, setPassword] = useState('ReliefLinkDemo!');
  const [pending, setPending] = useState(false);
  const submit = async (e: FormEvent) => { e.preventDefault(); setPending(true); try { await onLogin(email, password); } finally { setPending(false); } };
  return <div className="login-page"><div className="login-story"><Brand inverse /><div className="login-story-content"><div className="eyebrow light">A SHARED PURPOSE. A CLEARER RESPONSE.</div><h1>Help reaches further<br />when we work<br /><em>together.</em></h1><p>Connect community needs with the supplies, people and vehicles that can make a difference.</p><div className="login-network"><span className="network-orbit orbit-one" /><span className="network-orbit orbit-two" /><span className="network-orbit orbit-three" /><div className="network-heart"><HeartHandshake size={42} strokeWidth={1.4} /></div><span className="orbit-node node-one"><WarehouseIcon size={22} /></span><span className="orbit-node node-two"><Truck size={23} /></span><span className="orbit-node node-three"><Users size={23} /></span><span className="network-note note-one">Available supplies</span><span className="network-note note-two">Coordinated delivery</span><span className="network-note note-three">Community needs</span></div></div><div className="login-story-footer"><span>Built with purpose by Team Proxy</span><span>Disaster management</span></div></div><div className="login-main"><div className="login-top"><span className="local-dot" /> DEMO WORKSPACE</div><div className="login-form-wrap"><div className="login-welcome-icon"><ShieldCheck size={27} /></div><h2>Welcome to ReliefLink</h2><p>Sign in to your relief operations workspace.</p><form onSubmit={submit}><label className="field">Email address<input type="email" autoComplete="username" required value={email} onChange={e => setEmail(e.target.value)} /></label><label className="field">Password<input type="password" autoComplete="current-password" required value={password} onChange={e => setPassword(e.target.value)} /></label>{error && <div className="form-error" role="alert"><CircleAlert size={17} />{error}</div>}<button className="button primary login-submit" disabled={pending}>{pending ? <LoaderCircle className="spin" size={18} /> : <>Sign in to workspace<ArrowRight size={18} /></>}</button></form><div className="demo-accounts"><span className="eyebrow">EXPLORE THE DEMO</span><p>Sample accounts use <code>ReliefLinkDemo!</code></p><div><button onClick={() => { setEmail('coordinator@relieflink.local'); setPassword('ReliefLinkDemo!'); }}><ShieldCheck size={16} /><span>Coordinator<small>Manage and approve</small></span><ArrowUpRight size={15} /></button><button onClick={() => { setEmail('field@relieflink.local'); setPassword('ReliefLinkDemo!'); }}><Users size={16} /><span>Field worker<small>Report and verify</small></span><ArrowUpRight size={15} /></button></div></div></div><div className="login-bottom"><span><ShieldCheck size={14} /> Shared sample accounts · fictional data only.</span><small>ReliefLink · Team Proxy</small></div></div></div>;
}

export default function App() {
  const initialPage = window.location.hash.slice(1) as Page;
  const [page, setPage] = useState<Page>(NAV.some(n => n.id === initialPage) ? initialPage : 'overview');
  const [data, setData] = useState<Snapshot | null>(null);
  const [csrf, setCsrf] = useState('');
  const [booting, setBooting] = useState(true);
  const [error, setError] = useState('');
  const [toast, setToast] = useState<{ message: string; error?: boolean } | null>(null);
  const [busy, setBusy] = useState(false);
  const [modal, setModal] = useState<ModalState | null>(null);
  const [mobile, setMobile] = useState(false);
  const [notifications, setNotifications] = useState(false);
  const [planId, setPlanId] = useState<string | null>(null);
  const [synced, setSynced] = useState<Date | null>(null);
  const load = async () => { const s = await request<Snapshot>('/state'); setData(s); setSynced(new Date()); return s; };
  useEffect(() => { let alive = true; (async () => { try { const auth = await request<{ csrf_token: string }>('/auth/me'); if (!alive) return; setCsrf(auth.csrf_token); await load(); } catch (e) { if (alive && e instanceof Error && !/authenticat|session|login|sign.?in|not logged/i.test(e.message)) setError(e.message); } finally { if (alive) setBooting(false); } })(); return () => { alive = false; }; }, []);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(null), 5500); return () => clearTimeout(t); } }, [toast]);
  const navigate = (p: Page) => { setPage(p); window.location.hash = p; setMobile(false); };
  useEffect(() => { const change = () => { const p = window.location.hash.slice(1) as Page; if (NAV.some(n => n.id === p)) setPage(p); }; window.addEventListener('hashchange', change); return () => window.removeEventListener('hashchange', change); }, []);
  const save: Save = async (path, body = {}, method = 'POST', message = 'Changes saved') => {
    setBusy(true);
    try { await request(path, csrf, body, method); await load(); setToast({ message }); return true; }
    catch (e) { setToast({ message: e instanceof Error ? e.message : 'Unable to save changes.', error: true }); return false; }
    finally { setBusy(false); }
  };
  const generate = async () => { const ok = await save('/plans/generate', {}, 'POST', 'Allocation proposal ready for review.'); if (ok) { setPlanId(null); navigate('planning'); } };
  if (booting) return <div className="startup"><Brand /><LoaderCircle className="spin" size={25} /><span>Opening your workspace…</span></div>;
  if (!data) return <Login error={error} onLogin={async (email, password) => { setError(''); try { const auth = await request<{ csrf_token: string }>('/auth/login', '', { email, password }, 'POST'); setCsrf(auth.csrf_token); await load(); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to sign in.'); } }} />;
  const coordinator = data.user.role === 'coordinator';
  const open = (kind: ModalKind, id?: string) => setModal({ kind, id });
  const title = NAV.find(n => n.id === page)?.label || 'Overview';
  return <div className="app-shell"><aside className={`sidebar ${mobile ? 'sidebar-open' : ''}`}><Brand /><div className="workspace-switch"><span className="workspace-emblem"><MapPin size={16} /></span><div>Flood response<small>Bengaluru · sample scenario</small></div><ChevronDown size={15} /></div><span className="nav-label">WORKSPACE</span><nav aria-label="Main navigation">{NAV.map(n => <button key={n.id} className={page === n.id ? 'nav-active' : ''} onClick={() => navigate(n.id)}><n.icon size={19} strokeWidth={1.7} /><span>{n.label}</span>{n.id === 'deliveries' && data.summary.active_deliveries > 0 && <small>{data.summary.active_deliveries}</small>}</button>)}</nav><div className="sidebar-note"><span className="sidebar-note-icon"><HeartHandshake size={22} /></span><strong>Small actions.<br />Meaningful impact.</strong><p>One shared view. A better coordinated response.</p></div><div className="sidebar-bottom">{coordinator && <button onClick={() => open('settings')}><Settings2 size={18} />Workspace settings</button>}<div className="sidebar-team"><span className="team-avatar">P</span><div>Team Proxy<small>Disaster management</small></div><span className="local-dot" /></div></div></aside>{mobile && <button className="mobile-backdrop" aria-label="Close navigation" onClick={() => setMobile(false)} />}
    <div className="app-main"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={() => setMobile(true)}><Menu size={21} /></button><span>Workspace</span><ChevronRight size={13} /><strong>{title}</strong></div><div className="topbar-right"><span className="workspace-status"><span className="local-dot" />{data.storage === 'postgresql' ? 'Shared workspace' : 'Local workspace'}</span><span className="topbar-divider" /><button className="icon-button" title="Refresh server data" aria-label="Refresh server data" disabled={busy} onClick={async () => { try { await load(); setToast({ message: 'Workspace is up to date.' }); } catch { setToast({ message: 'Unable to refresh. Check the server connection.', error: true }); } }}><RefreshCw size={17} className={busy ? 'spin' : ''} /></button><div className="notification-wrapper"><button className="icon-button" aria-label="Recent activity" title="Recent activity" onClick={() => setNotifications(!notifications)}><Bell size={18} />{data.activity.length > 0 && <i className="notification-dot" />}</button>{notifications && <div className="notification-popover"><SectionHead title="Recent activity" right={<button className="icon-button" onClick={() => setNotifications(false)} aria-label="Close activity"><X size={16} /></button>} /><ActivityList events={data.activity} limit={4} /></div>}</div><div className="top-user"><span className="avatar">{data.user.name.split(' ').map(n => n[0]).slice(0, 2).join('')}</span><div><strong>{data.user.name}</strong><small>{label(data.user.role)}</small></div><button className="icon-button" title="Sign out" aria-label="Sign out" onClick={async () => { try { await request('/auth/logout', csrf, {}, 'POST'); setData(null); setCsrf(''); setError(''); } catch (e) { setToast({ message: (e as Error).message, error: true }); } }}><LogOut size={16} /></button></div></div></header>
      <main className="page-content"><div className="page-heading"><div><div className="eyebrow">RELIEF OPERATIONS <span> / </span> <span className="demo-label">SAMPLE SCENARIO</span></div><h1>{page === 'overview' ? 'A clearer view. A stronger response.' : title}</h1><p>{page === 'overview' ? 'Bring needs, resources and people together. Make every delivery count.' : page === 'needs' ? 'Listen to communities. Keep confirmed needs current and visible.' : page === 'resources' ? 'Know what is available, where it is, and how it can move.' : page === 'planning' ? 'Turn available resources into feasible, explainable delivery plans.' : page === 'deliveries' ? 'Follow every consignment from dispatch to an acknowledged receipt.' : 'See the work completed and the needs that still require attention.'}</p></div><div className="heading-actions">{page === 'overview' && <><button className="button secondary" onClick={() => open('request')}><Plus size={16} />Report a need</button>{coordinator && <button className="button primary" onClick={generate} disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : <RouteIcon size={17} />}Create allocation</button>}</>}{page === 'needs' && coordinator && <button className="button primary" onClick={() => open('location')}><Plus size={17} />Add location</button>}{page === 'planning' && coordinator && <button className="button primary" onClick={generate} disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : <Sparkles size={17} />}{busy ? 'Solving proposal…' : 'Generate proposal'}</button>}{page === 'reports' && <a className="button secondary" href="/api/export/deliveries.csv"><Download size={16} />Export deliveries</a>}</div></div>
      {page === 'overview' && <Overview data={data} navigate={navigate} open={open} />}
      {page === 'needs' && <Needs data={data} open={open} coordinator={coordinator} />}
      {page === 'resources' && <Resources data={data} open={open} save={save} coordinator={coordinator} busy={busy} />}
      {page === 'planning' && <Planning data={data} selectedId={planId} setSelectedId={setPlanId} coordinator={coordinator} busy={busy} save={save} generate={generate} />}
      {page === 'deliveries' && <Deliveries data={data} open={open} save={save} coordinator={coordinator} busy={busy} />}
      {page === 'reports' && <Reports data={data} />}
      <footer className="page-footer"><span><span className="local-dot" />{synced ? `Updated ${synced.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}` : 'Connected to server'}<span className="footer-dot">·</span>{data.storage === 'postgresql' ? 'Records saved to shared database' : 'All records saved locally'}</span><span>Thoughtfully built by <strong>Team Proxy</strong></span></footer></main>
    </div>{modal && <FormModal modal={modal} data={data} busy={busy} onClose={() => setModal(null)} save={save} />}{toast && <div className={`toast ${toast.error ? 'toast-error' : ''}`} role={toast.error ? 'alert' : 'status'}>{toast.error ? <CircleAlert size={19} /> : <CheckCheck size={19} />}<span>{toast.message}</span><button onClick={() => setToast(null)} aria-label="Dismiss message"><X size={16} /></button></div>}
  </div>;
}

function Overview({ data, navigate, open }: { data: Snapshot; navigate: (p: Page) => void; open: (kind: ModalKind, id?: string) => void }) {
  const priorities = [...data.locations].filter(l => ITEMS.some(k => remaining(l, k) > 0)).sort((a, b) => (PRIORITY[b.severity] || 0) - (PRIORITY[a.severity] || 0));
  const ready = data.vehicles.filter(v => v.status === 'available').length;
  const stock = Object.fromEntries(ITEMS.map(k => [k, data.warehouses.reduce((s, w) => s + w.stock[k] - w.reserved[k], 0)])) as Quantities;
  const needed = Object.fromEntries(ITEMS.map(k => [k, data.locations.reduce((s, l) => s + remaining(l, k), 0)])) as Quantities;
  return <><div className="metric-ribbon"><Metric icon={<Users size={21} />} name="Affected population" value={num(data.summary.population)} detail={`Across ${data.locations.length} registered locations`} /><Metric icon={<MapPin size={21} />} name="Locations with open needs" value={num(priorities.length)} detail={`${priorities.filter(l => l.severity === 'critical').length} marked critical priority`} accent /><Metric icon={<Truck size={21} />} name="Vehicles ready" value={`${ready.toString().padStart(2, '0')}`} detail={`of ${data.vehicles.length} in your response fleet`} /><Metric icon={<FileCheck2 size={21} />} name="Verified deliveries" value={data.summary.completed_deliveries.toString().padStart(2, '0')} detail={`${data.summary.active_deliveries} deliveries in progress`} /></div>
    <div className="overview-main"><section className="panel map-panel"><SectionHead title="Your operational picture" subtitle="Locations, supplies and the roads that connect them" right={<span className="tiny-label"><span className="local-dot" />{data.locations.length + data.warehouses.length} locations</span>} /><NetworkMap data={data} /><div className="map-panel-footer"><span><ShieldCheck size={14} />Sample road network · simulated routes</span><button className="text-button" onClick={() => navigate('resources')}>Manage network<ArrowRight size={14} /></button></div></section><section className="panel priorities-panel"><SectionHead title="Needs attention" right={<span className="count-pill">{priorities.length}</span>} /><p className="priorities-description">Start with the communities facing the most urgent needs.</p><div className="priority-list">{priorities.slice(0, 3).map((l, i) => <button key={l.id} className="priority-card" onClick={() => open('request', l.id)}><div className="priority-card-top"><span className={`priority-marker priority-${l.severity}`}>{String(i + 1).padStart(2, '0')}</span><Badge value={l.severity} /></div><strong>{l.name}</strong><span className="priority-population"><Users size={12} />{num(l.population)} people · {num(l.injured)} injured</span><div className="priority-shortage"><Droplets size={14} />{num(remaining(l, 'water'))} L water needed<ArrowUpRight size={15} /></div></button>)}{!priorities.length && <Empty title="Needs are covered" icon={<CheckCheck size={25} />}>No uncommitted needs are currently outstanding.</Empty>}</div><button className="button secondary priorities-view" onClick={() => navigate('needs')}>View all community needs<ArrowRight size={15} /></button></section></div>
    <div className="overview-bottom"><section className="panel"><SectionHead title="Supply readiness" subtitle="Available stock compared with outstanding needs" right={<button className="text-button" onClick={() => navigate('resources')}>View inventory<ArrowRight size={14} /></button>} /><div className="readiness-grid">{ITEMS.map(k => { const cover = needed[k] > 0 ? Math.min(100, stock[k] / needed[k] * 100) : 100; return <div className={`readiness-item readiness-${k}`} key={k}><span className="supply-icon"><ItemIcon item={k} size={20} /></span><span className="readiness-label">{ITEM_NAMES[k]}</span><div className="readiness-value">{num(stock[k])}<small>{UNITS[k]} available</small></div><div className="progress-track"><div style={{ width: `${Math.max(0, cover)}%` }} /></div><div className="readiness-detail"><span>{num(needed[k])} {UNITS[k]} needed</span><strong className={cover >= 100 ? 'text-green' : 'text-amber'}>{cover >= 100 ? 'Stock covers need' : `${Math.round(cover)}% covered`}</strong></div></div>; })}</div></section><section className="panel"><SectionHead title="Latest from your team" right={<button className="text-button" onClick={() => navigate('reports')}>All activity<ArrowRight size={14} /></button>} /><ActivityList events={data.activity} limit={3} /></section></div>
    <div className="workflow-strip"><span className="workflow-intro"><HeartHandshake size={19} />A connected response</span>{['Report needs', 'Plan allocation', 'Approve & dispatch', 'Verify receipt'].map((s, i) => <span key={s}><i>{i + 1}</i>{s}{i < 3 && <ChevronRight size={14} />}</span>)}</div>
  </>;
}
function Metric({ icon, name, value, detail, accent = false }: { icon: ReactNode; name: string; value: string; detail: string; accent?: boolean }) { return <div className={`metric ${accent ? 'metric-accent' : ''}`}><div className="metric-label">{name}<span>{icon}</span></div><div className="metric-value">{value}</div><p>{detail}</p></div>; }

function Needs({ data, open, coordinator }: { data: Snapshot; open: (kind: ModalKind, id?: string) => void; coordinator: boolean }) {
  const [query, setQuery] = useState(''); const [severity, setSeverity] = useState('all');
  const locations = data.locations.filter(l => l.name.toLowerCase().includes(query.toLowerCase()) && (severity === 'all' || l.severity === severity));
  return <><div className="information-note"><ShieldCheck size={18} /><span><strong>One current need per community.</strong> Reports update the total need, with received and already-committed supplies kept visible.</span><button className="text-button" onClick={() => open('request')}>Report a need<Plus size={15} /></button></div><section className="panel"><div className="table-toolbar"><div><h2>Affected locations <span className="inline-count">{data.locations.length}</span></h2><p>Quantities below show remaining, uncommitted need.</p></div><div className="table-filters"><div className="search-input"><Search size={16} /><input aria-label="Search locations" placeholder="Find a community…" value={query} onChange={e => setQuery(e.target.value)} /></div><label className="select-filter"><Filter size={14} /><select aria-label="Filter priority" value={severity} onChange={e => setSeverity(e.target.value)}><option value="all">All priorities</option>{['critical', 'high', 'moderate', 'low'].map(s => <option key={s} value={s}>{label(s)}</option>)}</select></label></div></div><div className="table-scroll"><table><thead><tr><th>COMMUNITY / LOCATION</th><th>POPULATION</th><th>PRIORITY</th><th>OPEN NEEDS</th><th /></tr></thead><tbody>{locations.map((l, i) => <tr key={l.id}><td><div className="entity-cell"><span className={`entity-icon severity-${l.severity}`}><MapPin size={18} /></span><div><strong>{l.name}</strong><small>{l.contact || `Location ${String(i + 1).padStart(2, '0')}`}<span> · </span>{l.lat.toFixed(3)}, {l.lng.toFixed(3)}</small></div></div></td><td><strong>{num(l.population)}</strong><small className="cell-sub">{num(l.injured)} reported injured</small></td><td><Badge value={l.severity} /></td><td><Cargo q={{ food: remaining(l, 'food'), water: remaining(l, 'water'), medical: remaining(l, 'medical') }} compact /></td><td><div className="row-actions"><button className="button small secondary" onClick={() => open('request', l.id)}>Update need</button>{coordinator && <button className="icon-button" aria-label={`Edit ${l.name}`} onClick={() => open('location', l.id)}><SlidersHorizontal size={16} /></button>}</div></td></tr>)}</tbody></table></div>{!locations.length && <Empty title="No matching communities" icon={<MapPin size={24} />}>Add a location or change your search to get started.</Empty>}</section><div className="needs-notes">{data.locations.map(l => <div className="panel mini-location" key={l.id}><div><strong>{l.name}</strong><Badge value={l.severity} /></div><p>{l.notes || 'No field notes recorded yet.'}</p><small>Verified received</small><Cargo q={l.received} /><small>Committed to active deliveries</small><Cargo q={l.committed} /></div>)}</div></>;
}

function Resources({ data, open, save, coordinator, busy }: { data: Snapshot; open: (kind: ModalKind, id?: string) => void; save: Save; coordinator: boolean; busy: boolean }) {
  const [tab, setTab] = useState('warehouses');
  const nodes = [...data.locations, ...data.warehouses];
  return <><div className="tabs resource-tabs">{[{ id: 'warehouses', title: 'Warehouses', icon: WarehouseIcon, count: data.warehouses.length }, { id: 'fleet', title: 'Response fleet', icon: Truck, count: data.vehicles.length }, { id: 'roads', title: 'Road network', icon: RouteIcon, count: data.roads.length }].map(t => <button key={t.id} className={tab === t.id ? 'tab-active' : ''} onClick={() => setTab(t.id)}><t.icon size={17} />{t.title}<span>{t.count}</span></button>)}</div>
    {tab === 'warehouses' && <><div className="section-subhead"><p>Stock is reserved on approval and deducted on dispatch.</p>{coordinator && <button className="button secondary" onClick={() => open('warehouse')}><Plus size={16} />Add warehouse</button>}</div><div className="warehouse-grid">{data.warehouses.map((w, i) => <section className="panel warehouse-card" key={w.id}><div className="warehouse-top"><span className="warehouse-symbol"><WarehouseIcon size={24} strokeWidth={1.5} /></span><span className="warehouse-number">DEPOT {String(i + 1).padStart(2, '0')}</span><span className="tiny-label"><span className="local-dot" />Operational</span></div><h2>{w.name}</h2><p className="warehouse-coordinates"><MapPin size={12} />{w.lat.toFixed(4)}° N, {w.lng.toFixed(4)}° E</p><div className="stock-list">{ITEMS.map(k => <div className="stock-row" key={k}><span className={`stock-item stock-${k}`}><ItemIcon item={k} size={17} /></span><div><span>{ITEM_NAMES[k]}</span><div className="progress-track"><div style={{ width: `${w.stock[k] ? Math.min(100, Math.max(0, (w.stock[k] - w.reserved[k]) / w.stock[k] * 100)) : 0}%` }} /></div><small>{num(w.reserved[k])} reserved · {num(w.stock[k])} on hand</small></div><strong>{num(w.stock[k] - w.reserved[k])}<small>{UNITS[k]}</small></strong></div>)}</div><div className="warehouse-bottom"><span><Truck size={14} />{data.vehicles.filter(v => v.warehouse_id === w.id).length} assigned vehicles</span>{coordinator && <button className="text-button" onClick={() => open('restock', w.id)}>Receive stock<Plus size={14} /></button>}</div></section>)}</div>{!data.warehouses.length && <section className="panel"><Empty title="Your stock network starts here">Register your first warehouse and record its available supplies.</Empty></section>}</>}
    {tab === 'fleet' && <section className="panel"><SectionHead title="Response vehicles" subtitle="Every vehicle loads at and returns to its home warehouse." right={coordinator && <button className="button primary" onClick={() => open('vehicle')} disabled={!data.warehouses.length}><Plus size={16} />Add vehicle</button>} /><div className="table-scroll"><table><thead><tr><th>VEHICLE</th><th>HOME WAREHOUSE</th><th>PAYLOAD CAPACITY</th><th>STATUS</th><th /></tr></thead><tbody>{data.vehicles.map(v => <tr key={v.id}><td><div className="entity-cell"><span className="entity-icon"><Truck size={20} /></span><strong>{v.name}</strong></div></td><td>{data.warehouses.find(w => w.id === v.warehouse_id)?.name || 'Unassigned'}</td><td><strong>{num(v.capacity_kg)}</strong> <span className="muted">kg</span></td><td><Badge value={v.status} /></td><td>{coordinator && ['available', 'maintenance'].includes(v.status) && <button className="button small secondary" disabled={busy} onClick={() => save(`/vehicles/${v.id}`, { status: v.status === 'available' ? 'maintenance' : 'available' }, 'PATCH', 'Vehicle availability updated.')}>{v.status === 'available' ? 'Mark maintenance' : 'Make available'}</button>}</td></tr>)}</tbody></table></div>{!data.vehicles.length && <Empty title="No vehicles yet" icon={<Truck size={25} />}>Add a vehicle to make deliveries possible.</Empty>}</section>}
    {tab === 'roads' && <section className="panel"><SectionHead title="Modelled road connections" subtitle="Closing a road changes the graph used by the next planning run." right={<span className="badge badge-moderate">Sample travel times</span>} /><NetworkMap data={data} /><div className="table-scroll"><table><thead><tr><th>CONNECTION</th><th>DISTANCE</th><th>TRAVEL TIME</th><th>STATUS</th><th /></tr></thead><tbody>{data.roads.map(r => <tr key={r.id}><td><strong>{nodes.find(n => n.id === r.from_id)?.name}</strong><span className="road-connector"><ArrowRight size={13} /></span><span>{nodes.find(n => n.id === r.to_id)?.name}</span></td><td>{num(r.distance_km)} km</td><td>{num(r.minutes)} min</td><td><Badge value={r.blocked ? 'blocked' : 'available'}>{r.blocked ? 'Closed' : 'Open'}</Badge></td><td>{coordinator && <button className={`button small ${r.blocked ? 'secondary' : 'danger-outline'}`} disabled={busy} onClick={() => save(`/roads/${r.id}`, { blocked: !r.blocked }, 'PATCH', r.blocked ? 'Road reopened.' : 'Road closure recorded. Generate a new proposal to replan.')}>{r.blocked ? 'Reopen road' : 'Close road'}</button>}</td></tr>)}</tbody></table></div></section>}
  </>;
}

function Planning({ data, selectedId, setSelectedId, coordinator, busy, save, generate }: { data: Snapshot; selectedId: string | null; setSelectedId: (id: string) => void; coordinator: boolean; busy: boolean; save: Save; generate: () => Promise<void> }) {
  const sorted = [...data.plans].sort((a, b) => b.created_at.localeCompare(a.created_at));
  const plan = sorted.find(p => p.id === selectedId) || sorted[0];
  if (!plan) return <section className="panel planning-empty"><div className="plan-illustration"><WarehouseIcon size={28} /><span /><Truck size={36} /><span /><MapPin size={29} /></div><Empty title="Good coordination starts with a plan." icon={<RouteIcon size={29} />} action={coordinator && <button className="button primary" disabled={busy} onClick={generate}>{busy ? <LoaderCircle className="spin" size={16} /> : <Sparkles size={16} />}Generate first proposal</button>}>The planner considers community urgency, available supplies, vehicle payloads and reachable roads together. Review its recommendations before anything is dispatched.</Empty><div className="planning-principles"><span><Check size={15} />Capacity-aware</span><span><Check size={15} />Stock constrained</span><span><Check size={15} />Coordinator approved</span></div></section>;
  const result = plan.result;
  const stale = plan.status === 'draft' && plan.input_version !== data.version;
  const shortages = result.shortages.filter(s => total(s.remaining) > 0);
  const blockedLocations = result.road_blocked_locations ?? [];
  return <><div className="plan-toolbar"><div><select className="plan-selector" aria-label="Select allocation proposal" value={plan.id} onChange={e => setSelectedId(e.target.value)}>{sorted.map(p => <option key={p.id} value={p.id}>Proposal {p.id.slice(-6).toUpperCase()} · {new Date(p.created_at).toLocaleString('en-IN')} · {label(p.status)}</option>)}</select><Badge value={plan.status} /><span className="tiny-label">Solver: {result.status}</span></div><span className="muted">Review before approval</span></div>{stale && <div className="warning-note"><CircleAlert size={18} />Resources or needs changed after this proposal was generated. Generate a fresh proposal before approval.</div>}{blockedLocations.map(location => <div className="warning-note road-blocked-warning" role="status" key={location.location_id}><CircleAlert size={18} aria-hidden="true" /><p><strong>Cannot deliver to {location.location_name}:</strong> all road routes from warehouses are blocked. Its needs remain outstanding.</p></div>)}<div className="metric-ribbon planning-metrics"><Metric icon={<Package size={20} />} name="Planned relief cargo" value={`${num(result.total_kg)} kg`} detail="Across all proposed vehicle manifests" /><Metric icon={<Truck size={20} />} name="Vehicle tours" value={num(result.routes.length)} detail="Each returns to its home warehouse" /><Metric icon={<Clock3 size={20} />} name="Modelled travel" value={`${num(result.travel_minutes)} min`} detail={`${num(result.distance_km)} km across the sample road network`} /><Metric icon={<CircleAlert size={20} />} name="Remaining shortages" value={num(shortages.length)} detail="Locations needing a follow-up response" accent /></div><div className="panel"><SectionHead title="A feasible route for every allocation" subtitle="Quantities and routes are solved together by OR-Tools." right={<Cargo q={result.total_allocated} compact />} /><NetworkMap data={data} routes={result.routes} large /><div className="plan-explanation"><ShieldCheck size={20} /><div><strong>Why this plan?</strong><p>{result.explanation}</p></div></div><div className="plan-approval"><div><Badge value={plan.status} /><p>{plan.status === 'draft' ? 'Approval reserves warehouse stock and vehicle capacity.' : plan.status === 'approved' ? 'Reservations are held. Your team can now dispatch these deliveries.' : 'This proposal is no longer active.'}</p></div>{coordinator && <div className="row-actions">{['draft', 'approved'].includes(plan.status) && <button className="button secondary" disabled={busy} onClick={() => save(`/plans/${plan.id}/cancel`, {}, 'POST', 'Proposal cancelled and any held reservations released.')}>{plan.status === 'approved' && data.deliveries.some(d => d.plan_id === plan.id && ['dispatched', 'verified'].includes(d.status)) ? 'Cancel remaining' : 'Cancel proposal'}</button>}{plan.status === 'draft' && <button className="button primary" disabled={busy || stale || !result.routes.length} onClick={() => save(`/plans/${plan.id}/approve`, {}, 'POST', 'Plan approved. Stock reserved and deliveries created.')}><ShieldCheck size={17} />Approve allocation</button>}</div>}</div></div><div className="routes-grid">{result.routes.map((r, i) => <section className="panel route-card" key={r.vehicle_id}><div className="route-card-top"><span className={`route-number route-color-${i % 3}`}>{String(i + 1).padStart(2, '0')}</span><div><h2>{r.vehicle_name}</h2><p>{r.warehouse_name} → {r.stops.length} stop{r.stops.length !== 1 ? 's' : ''} → return</p></div><strong>{num(r.travel_minutes)}<small>minutes</small></strong></div><div className="vehicle-load"><div><span>Payload utilisation</span><strong>{num(r.load_kg)} / {num(r.capacity_kg)} kg</strong></div><div className="progress-track"><div style={{ width: `${Math.min(100, r.load_kg / r.capacity_kg * 100)}%` }} /></div></div><div className="route-stops">{r.stops.map(stop => <div className="route-stop" key={stop.location_id}><span>{stop.sequence}</span><div><strong>{stop.location_name}</strong><Cargo q={stop.manifest} compact /></div></div>)}</div></section>)}</div>{shortages.length > 0 && <section className="panel"><SectionHead title="Still needing support" subtitle="Unmet quantities remain visible for the next planning cycle." /><div className="table-scroll"><table><thead><tr><th>LOCATION</th><th>PRIORITY WEIGHT</th><th>REMAINING NEED</th></tr></thead><tbody>{shortages.map(s => <tr key={s.location_id}><td><strong>{s.location_name}</strong></td><td>{s.priority}× urgency</td><td><Cargo q={s.remaining} /></td></tr>)}</tbody></table></div></section>}<details className="assumptions"><summary>Planning assumptions and solver methodology</summary><p>First minimise priority-weighted unmet need, then minimise modelled travel time. The solver may return a feasible rather than proven optimal result within its time budget.</p><ul>{result.assumptions.map((s, i) => <li key={i}>{s}</li>)}</ul><p>Urgency weights: critical 5, high 3, moderate 2, low 1. Item weights: medical 3, water 2, food 1. These are transparent demonstration assumptions.</p></details></>;
}

function Deliveries({ data, open, save, coordinator, busy }: { data: Snapshot; open: (kind: ModalKind, id?: string) => void; save: Save; coordinator: boolean; busy: boolean }) {
  const [filter, setFilter] = useState('all');
  const list = data.deliveries.filter(d => filter === 'all' || d.status === filter);
  return <><div className="delivery-summary"><div><span className="delivery-summary-icon"><Package size={23} /></span><span><strong>{data.deliveries.filter(d => d.status === 'reserved').length}</strong> Ready to dispatch</span></div><div><span className="delivery-summary-icon amber"><Truck size={23} /></span><span><strong>{data.deliveries.filter(d => d.status === 'dispatched').length}</strong> On the road</span></div><div><span className="delivery-summary-icon green"><CheckCheck size={23} /></span><span><strong>{data.deliveries.filter(d => d.status === 'verified').length}</strong> Receipts verified</span></div></div><div className="section-subhead"><div className="tabs compact-tabs">{['all', 'reserved', 'dispatched', 'verified'].map(s => <button key={s} className={filter === s ? 'tab-active' : ''} onClick={() => setFilter(s)}>{s === 'all' ? 'All deliveries' : s === 'reserved' ? 'Ready to dispatch' : label(s)}</button>)}</div><a className="text-button" href="/api/export/deliveries.csv"><ArrowDownToLine size={15} />Export manifests</a></div><div className="delivery-grid">{list.map(d => { const location = data.locations.find(l => l.id === d.location_id); const vehicle = data.vehicles.find(v => v.id === d.vehicle_id); const warehouse = data.warehouses.find(w => w.id === d.warehouse_id); const discrepancy = d.received && ITEMS.some(k => d.received![k] < d.manifest[k]); return <section className="panel delivery-card" key={d.id}><div className="delivery-card-heading"><span className="delivery-code">DLV · {d.id.slice(-7).toUpperCase()}</span><Badge value={d.status} /></div><h2>{location?.name || d.location_id}</h2><p className="delivery-origin"><WarehouseIcon size={14} />From {warehouse?.name || d.warehouse_id}</p><div className="delivery-progress">{['reserved', 'dispatched', 'verified'].map((s, i) => <div className={['reserved', 'dispatched', 'verified'].indexOf(d.status) >= i ? 'step-complete' : ''} key={s}><span>{['reserved', 'dispatched', 'verified'].indexOf(d.status) > i ? <Check size={12} /> : i + 1}</span><small>{s === 'reserved' ? 'Reserved' : s === 'dispatched' ? 'Dispatched' : 'Verified'}</small></div>)}</div><div className="delivery-manifest"><span className="eyebrow">DISPATCH MANIFEST</span><Cargo q={d.manifest} /></div>{d.received && <div className={`receipt-box ${discrepancy ? 'receipt-discrepancy' : ''}`}><div><FileCheck2 size={15} /><strong>{discrepancy ? 'Receipt recorded · discrepancy' : 'Receipt verified'}</strong></div><Cargo q={d.received} compact /><p>Acknowledged by {d.recipient}{d.verified_at ? ` · ${time(d.verified_at)}` : ''}</p>{d.notes && <p>{d.notes}</p>}</div>}<div className="delivery-card-bottom"><span><Truck size={15} />{vehicle?.name || d.vehicle_id}</span>{d.status === 'reserved' && coordinator && <button className="button small primary" disabled={busy} onClick={() => save(`/deliveries/${d.id}/dispatch`, {}, 'POST', 'Vehicle tour dispatched. Stock deducted for every stop on this tour.')}><Truck size={14} />Dispatch tour</button>}{d.status === 'dispatched' && (coordinator || d.assigned_user_id === data.user.id) && <button className="button small primary" onClick={() => open('verify', d.id)}><FileCheck2 size={14} />Verify receipt</button>}</div></section>; })}</div>{!list.length && <section className="panel"><Empty title="No deliveries in this view" icon={<Truck size={28} />}>Approved proposals create delivery manifests. Dispatch a tour and record the actual quantities received at each location.</Empty></section>}</>;
}

function Reports({ data }: { data: Snapshot }) {
  const received = Object.fromEntries(ITEMS.map(k => [k, data.locations.reduce((s, l) => s + l.received[k], 0)])) as Quantities;
  const manifest = Object.fromEntries(ITEMS.map(k => [k, data.deliveries.filter(d => d.status === 'verified').reduce((s, d) => s + d.manifest[k], 0)])) as Quantities;
  const receipts = Object.fromEntries(ITEMS.map(k => [k, data.deliveries.filter(d => d.status === 'verified').reduce((s, d) => s + (d.received?.[k] || 0), 0)])) as Quantities;
  const discrepancies = data.deliveries.filter(d => d.received && ITEMS.some(k => d.received![k] < d.manifest[k]));
  return <><div className="information-note"><ShieldCheck size={18} /><span>These figures are calculated from saved records. Sample data is for demonstration; no historical impact improvements are assumed.</span></div><div className="metric-ribbon"><Metric icon={<Package size={21} />} name="Food received" value={num(received.food)} detail="Food packets acknowledged by recipients" /><Metric icon={<Droplets size={21} />} name="Water received" value={`${num(received.water)} L`} detail="Drinking water acknowledged by recipients" /><Metric icon={<Stethoscope size={21} />} name="Medical kits received" value={num(received.medical)} detail="Kits acknowledged by recipients" /><Metric icon={<CircleAlert size={21} />} name="Receipt discrepancies" value={num(discrepancies.length)} detail="Deliveries with short-received quantities" accent /></div><div className="reports-grid"><section className="panel"><SectionHead title="Chain of custody" subtitle="Compare dispatched and acknowledged quantities for verified deliveries." /><div className="custody-list">{ITEMS.map(k => <div key={k}><div className="custody-heading"><span><ItemIcon item={k} size={17} />{ITEM_NAMES[k]}</span><strong>{num(receipts[k])} / {num(manifest[k])} {UNITS[k]}</strong></div><div className="progress-track"><div style={{ width: `${manifest[k] > 0 ? Math.min(100, receipts[k] / manifest[k] * 100) : 0}%` }} /></div><small>{num(Math.max(0, manifest[k] - receipts[k]))} {UNITS[k]} recorded as missing</small></div>)}</div></section><section className="panel export-panel"><SectionHead title="Take the records with you" subtitle="CSV exports reflect the current workspace records." />{[{ kind: 'needs', title: 'Community needs', detail: 'Current needs, received and committed supplies', icon: HeartHandshake }, { kind: 'deliveries', title: 'Delivery manifests', detail: 'Dispatches, receipts and discrepancies', icon: Truck }, { kind: 'activity', title: 'Team activity', detail: 'Recorded actions and accountability history', icon: Activity }].map(e => <a href={`/api/export/${e.kind}.csv`} className="export-item" key={e.kind}><span><e.icon size={20} /></span><div><strong>{e.title}</strong><small>{e.detail}</small></div><Download size={17} /></a>)}</section></div><section className="panel"><SectionHead title="Workspace activity" subtitle="A saved history of actions by your response team." right={<span className="tiny-label">{data.activity.length} recent records</span>} /><ActivityList events={data.activity} limit={40} /></section></>;
}

function FormModal({ modal, data, onClose, save, busy }: { modal: ModalState; data: Snapshot; onClose: () => void; save: Save; busy: boolean }) {
  const dialog = useRef<HTMLDialogElement>(null);
  const location = data.locations.find(l => l.id === modal.id);
  const warehouse = data.warehouses.find(w => w.id === modal.id);
  const delivery = data.deliveries.find(d => d.id === modal.id);
  const [values, setValues] = useState<Record<string, string>>(() => {
    const l = location || data.locations[0];
    const initialNeed = modal.kind === 'location' && !location ? { food: Math.ceil(250 * data.settings.food_per_person), water: Math.ceil(250 * data.settings.water_per_person), medical: 0 } : l?.demands;
    return { name: modal.kind === 'warehouse' ? '' : location?.name || '', lat: String(location?.lat ?? 12.9716), lng: String(location?.lng ?? 77.5946), population: String(location?.population ?? 250), injured: String(location?.injured ?? 0), severity: location?.severity || 'moderate', contact: location?.contact || '', notes: modal.kind === 'location' ? location?.notes || '' : '', location_id: l?.id || '', food: String(modal.kind === 'verify' ? delivery?.manifest.food || 0 : modal.kind === 'restock' || modal.kind === 'warehouse' ? 0 : initialNeed?.food || 0), water: String(modal.kind === 'verify' ? delivery?.manifest.water || 0 : modal.kind === 'restock' || modal.kind === 'warehouse' ? 0 : initialNeed?.water || 0), medical: String(modal.kind === 'verify' ? delivery?.manifest.medical || 0 : modal.kind === 'restock' || modal.kind === 'warehouse' ? 0 : initialNeed?.medical || 0), warehouse_id: data.warehouses[0]?.id || '', capacity_kg: '1000', recipient: '', food_per_person: String(data.settings.food_per_person), water_per_person: String(data.settings.water_per_person), medical_per_injured: String(data.settings.medical_per_injured), confirmation: '' };
  });
  const [localError, setLocalError] = useState('');
  useEffect(() => { dialog.current?.showModal(); }, []);
  const set = (name: string, value: string) => setValues(v => ({ ...v, [name]: value }));
  const number = (name: string) => Number(values[name]);
  const quantities = () => ({ food: number('food'), water: number('water'), medical: number('medical') });
  const titles: Record<ModalKind, string> = { location: location ? 'Edit community location' : 'Register a community', request: 'Update confirmed needs', warehouse: 'Add a warehouse', restock: 'Receive warehouse stock', vehicle: 'Add a response vehicle', verify: 'Acknowledge delivery receipt', settings: 'Workspace settings', reset: 'Reset the sample scenario' };
  const subtitles: Record<ModalKind, string> = { location: 'Give your team a clear picture of the people and needs at this location.', request: 'Set the current total need. This replaces the previous request, rather than adding it twice.', warehouse: 'Record a supply location and its opening inventory.', restock: `Record newly received quantities at ${warehouse?.name || 'this warehouse'}.`, vehicle: 'Assign a payload capacity and home warehouse for its delivery tours.', verify: 'Record the quantities actually received, and acknowledge any discrepancy.', settings: 'Adjust the illustrative assumptions used to prefill demand estimates.', reset: 'This replaces all demo records with the original five-location scenario.' };
  const estimate = () => {
    const l = modal.kind === 'location' ? { population: number('population'), injured: number('injured') } : data.locations.find(l => l.id === values.location_id);
    if (l) setValues(v => ({ ...v, food: String(Math.ceil(l.population * data.settings.food_per_person)), water: String(Math.ceil(l.population * data.settings.water_per_person)), medical: String(Math.ceil(l.injured * data.settings.medical_per_injured)) }));
  };
  const submit = async (e: FormEvent) => {
    e.preventDefault(); setLocalError(''); let ok = false;
    if (modal.kind === 'location') ok = await save(`/locations${location ? `/${location.id}` : ''}`, { name: values.name, lat: number('lat'), lng: number('lng'), population: number('population'), injured: number('injured'), severity: values.severity, contact: values.contact, notes: values.notes, demands: quantities() }, location ? 'PATCH' : 'POST', location ? 'Community location updated.' : 'Community registered and connected to the sample road network.');
    if (modal.kind === 'request') ok = await save('/requests', { location_id: values.location_id, ...quantities(), notes: values.notes }, 'POST', 'Confirmed needs updated. Previous requests were not double-counted.');
    if (modal.kind === 'warehouse') ok = await save('/warehouses', { name: values.name, lat: number('lat'), lng: number('lng'), stock: quantities() }, 'POST', 'Warehouse added to the resource network.');
    if (modal.kind === 'restock') ok = await save(`/warehouses/${modal.id}/restock`, quantities(), 'POST', 'Stock receipt recorded.');
    if (modal.kind === 'vehicle') ok = await save('/vehicles', { name: values.name, warehouse_id: values.warehouse_id, capacity_kg: number('capacity_kg') }, 'POST', 'Response vehicle added.');
    if (modal.kind === 'verify' && delivery) { const missing = ITEMS.some(k => number(k) < delivery.manifest[k]); if (missing && !values.notes.trim()) { setLocalError('Please describe the discrepancy before verifying a short receipt.'); return; } ok = await save(`/deliveries/${delivery.id}/verify`, { ...quantities(), recipient: values.recipient, notes: values.notes }, 'POST', 'Receipt saved. Received supplies and remaining needs are updated.'); }
    if (modal.kind === 'settings') ok = await save('/settings', { food_per_person: number('food_per_person'), water_per_person: number('water_per_person'), medical_per_injured: number('medical_per_injured') }, 'PATCH', 'Planning assumptions updated. Existing confirmed requests are unchanged.');
    if (modal.kind === 'reset') { if (values.confirmation !== 'RESET') { setLocalError('Type RESET to confirm.'); return; } ok = await save('/demo/reset', { confirm: true }, 'POST', 'Sample scenario restored.'); }
    if (ok) onClose(); else setLocalError('The change was not saved. See the error message and check your entries.');
  };
  const input = (name: string, title: string, type = 'text', extras: Record<string, unknown> = {}) => <label className="field">{title}<input name={name} type={type} value={values[name] || ''} onChange={e => set(name, e.target.value)} required {...extras} /></label>;
  const current = data.locations.find(l => l.id === values.location_id);
  return <dialog ref={dialog} className="form-dialog" aria-labelledby="relieflink-dialog-title" aria-describedby="relieflink-dialog-description" onCancel={e => { if (busy) e.preventDefault(); else onClose(); }} onClick={e => { if (e.target === e.currentTarget && !busy) onClose(); }}><div className="dialog-content"><div className="dialog-heading"><div><span className="eyebrow">RELIEFLINK WORKSPACE</span><h2 id="relieflink-dialog-title">{titles[modal.kind]}</h2><p id="relieflink-dialog-description">{subtitles[modal.kind]}</p></div><button className="icon-button" type="button" aria-label="Close dialog" onClick={onClose} disabled={busy}><X size={20} /></button></div><form onSubmit={submit}><div className="dialog-fields">
    {(modal.kind === 'location' || modal.kind === 'warehouse' || modal.kind === 'vehicle') && input('name', modal.kind === 'vehicle' ? 'Vehicle name / registration' : 'Name')}
    {(modal.kind === 'location' || modal.kind === 'warehouse') && <div className="form-grid">{input('lat', 'Latitude', 'number', { min: -90, max: 90, step: 'any' })}{input('lng', 'Longitude', 'number', { min: -180, max: 180, step: 'any' })}</div>}
    {modal.kind === 'location' && <><div className="form-grid">{input('population', 'Affected population', 'number', { min: 0, step: 1 })}{input('injured', 'Reported injured', 'number', { min: 0, step: 1, max: number('population') })}</div><div className="form-grid"><label className="field">Urgency<select value={values.severity} onChange={e => set('severity', e.target.value)}>{['low', 'moderate', 'high', 'critical'].map(s => <option key={s} value={s}>{label(s)}</option>)}</select></label>{input('contact', 'Contact person', 'text', { required: false })}</div></>}
    {modal.kind === 'request' && <label className="field">Community location<select value={values.location_id} required onChange={e => { const l = data.locations.find(l => l.id === e.target.value); setValues(v => ({ ...v, location_id: e.target.value, food: String(l?.demands.food || 0), water: String(l?.demands.water || 0), medical: String(l?.demands.medical || 0) })); }}><option value="">Select a community</option>{data.locations.map(l => <option value={l.id} key={l.id}>{l.name}</option>)}</select></label>}
    {modal.kind === 'verify' && delivery && <div className="verify-manifest"><span>Dispatched to {data.locations.find(l => l.id === delivery.location_id)?.name}</span><Cargo q={delivery.manifest} /></div>}
    {['location', 'request', 'warehouse', 'restock', 'verify'].includes(modal.kind) && <div className="quantity-fields"><div className="quantity-heading"><strong>{modal.kind === 'verify' ? 'Actually received' : modal.kind === 'restock' ? 'New stock received' : modal.kind === 'warehouse' ? 'Opening inventory' : 'Total confirmed need'}</strong>{['location', 'request'].includes(modal.kind) && <button type="button" className="text-button" onClick={estimate}><Sparkles size={13} />Use demo estimates</button>}</div><div className="form-grid three">{ITEMS.map(k => <label className="field" key={k}><span><ItemIcon item={k} size={14} />{ITEM_NAMES[k]}</span><div className="unit-input"><input type="number" name={k} min={modal.kind === 'request' && current ? (current.received[k] + current.committed[k]) : 0} max={modal.kind === 'verify' ? delivery?.manifest[k] : undefined} step="1" required value={values[k]} onChange={e => set(k, e.target.value)} /><small>{UNITS[k]}</small></div></label>)}</div>{['location', 'request'].includes(modal.kind) && <p className="field-hint">Estimates use editable demonstration coefficients. Confirm the quantities with field reports before saving.</p>}</div>}
    {modal.kind === 'vehicle' && <><label className="field">Home warehouse<select required value={values.warehouse_id} onChange={e => set('warehouse_id', e.target.value)}>{data.warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select></label>{input('capacity_kg', 'Maximum payload (kg)', 'number', { min: 1, step: 1 })}<p className="field-hint">The vehicle loads at this warehouse and returns after its assigned tour.</p></>}
    {modal.kind === 'verify' && input('recipient', 'Recipient / acknowledging officer')}
    {['location', 'request', 'verify'].includes(modal.kind) && <label className="field">{modal.kind === 'verify' ? 'Receipt or discrepancy notes' : 'Field notes'}<textarea value={values.notes} onChange={e => set('notes', e.target.value)} rows={3} placeholder={modal.kind === 'verify' ? 'Describe missing quantities or the condition of the delivery…' : 'Useful context for the coordination team…'} /></label>}
    {modal.kind === 'settings' && <><div className="information-note"><CircleAlert size={17} /><span>These coefficients are illustrative planning inputs, not validated humanitarian standards.</span></div>{input('food_per_person', 'Food packets per person', 'number', { min: 0, step: '.1' })}{input('water_per_person', 'Water litres per person', 'number', { min: 0, step: '.1' })}{input('medical_per_injured', 'Medical kits per injured person', 'number', { min: 0, step: '.1' })}<div className="reset-area"><strong>Sample workspace</strong><p>Restore the original sample locations, stock, vehicles and road network. This removes subsequent demo actions.</p><button className="button small danger-outline" type="button" onClick={() => { if (window.confirm('Reset all sample records? This cannot be undone.')) save('/demo/reset', { confirm: true }, 'POST', 'Sample scenario restored.').then(ok => { if (ok) onClose(); }); }}>Reset sample data</button></div></>}
    {modal.kind === 'reset' && input('confirmation', 'Type RESET to confirm')}
    {localError && <div className="form-error" role="alert"><CircleAlert size={17} />{localError}</div>}
    </div><div className="dialog-footer"><button type="button" className="button secondary" onClick={onClose} disabled={busy}>Cancel</button><button type="submit" className="button primary" disabled={busy || (modal.kind === 'request' && !data.locations.length)}>{busy ? <LoaderCircle className="spin" size={16} /> : modal.kind === 'verify' ? <FileCheck2 size={16} /> : <Check size={16} />}{modal.kind === 'verify' ? 'Confirm actual receipt' : modal.kind === 'settings' ? 'Save settings' : 'Save changes'}</button></div></form></div></dialog>;
}
